WmlGuestFunction original_damage=nullptr;
void DamageHook(WmlContext* c,uint8_t* b) {
  // A replayed shot of another player hurts no one here (TryRemoteShots).
  if(fire_replay_depth) { api->set_f(c,1,0.0); return; }
  const uint32_t victim=uint32_t(api->get_r(c,3)), attacker=uint32_t(api->get_r(c,4));
  const int victim_slot=victim ? AvatarSlotOf(victim) : -1;   // another player's character
  const uint32_t sp=uint32_t(api->get_r(c,1));
  // Joiner: copies of the host's people take no damage here. Our player's
  // hits on them go to the host, whose game applies them to the real person
  // (a kill there comes back as a death).
  // Joiner: this game's own mission characters are hidden while the host's
  // are shown; hidden ones don't hurt anyone. (3.0 phase 2c: the mission
  // host's are shown on every game that runs its mission: IsMissionHost.)
  if(connected.load() && !IsMissionHost() && attacker && Readable(attacker,4252) && api->read_u32(attacker+72)==1 &&
     (api->read_u32(attacker+120)&0x08000000u)) { api->set_f(c,1,0.0); return; }
  // 2.1, joiner: a copy of another game's people (on foot, in a car, a
  // stand-in) hurts our player only through its owner, whose person's hits on
  // our character there come here replayed (kEventPlayerHitByPed); a local hit
  // would count twice. Not explosions or fire (each game plays them on its own
  // player, R 3.0), nor a car hitting our player (82451C98, from the contact
  // callback 82278E18, with its driver as the attacker): the owner's car hits
  // our character there with no damage.
  if(connected.load() && WorldViews() && !replicated_depth && !explosion_depth && !fire_update_depth && victim &&
     victim==api->read_u32(0x8309ABEC) && attacker && Readable(attacker,4252) && api->read_u32(attacker+72)==1 &&
     !CarHitsPerson(api->get_lr(c)) && OurCharacter(api->read_u32(attacker+68))) {
    ++copy_hits_zeroed; api->set_f(c,1,0.0); return;
  }
  // A copy of another game's person (crews too: 2.2, an id of its owner's;
  // spec A/11) takes no damage here: our player's hit goes to its owner by its
  // NetId, and the owner's game applies it to the real person (a kill there
  // comes back as a death). Not from an explosion, nor from the burning people
  // update 8245ED40 (burn ticks and the fire spreading to people nearby): each
  // game plays the same explosion and its fire (R 3.0).
  // (3.0 phase 2c, shared) The same for a hit by one of this game's own
  // people (its cops, gang members, a mission's enemies on another owner's
  // copies), with the attacker named first (kEventHitBy).
  if(connected.load() && WorldViews() && !replicated_depth && victim && Readable(victim,4252) && WorldPersonId(api->read_u32(victim+68),true)) {
    const bool ours=attacker && attacker==api->read_u32(0x8309ABEC);
    const bool own_person=!ours && world_mode_shared && attacker && WorldOwnPerson(attacker);
    if((ours || own_person) && !explosion_depth && !fire_update_depth)
      if(const PersonNet pn=NetOfPerson(api->read_u32(victim+68)); pn.owner<kSlots) {
        if(own_person) {
          const PersonNet an=NetOfPerson(api->read_u32(attacker+68));
          QueueEventTo(Event{kEventHitBy,{an.handle,an.tag},0},pn.owner); ++npc_hits_sent;
        }
        Event e{kEventPedDamage,{pn.handle,uint32_t(api->get_r(c,5)),uint32_t(api->get_r(c,6)),uint32_t(api->get_r(c,7)),
                                 uint32_t(api->get_r(c,8)),uint32_t(api->get_r(c,9)),uint32_t(api->get_r(c,10)),
                                 uint32_t(api->read_u8(sp+87))|uint32_t(api->read_u8(sp+95))<<8|coopworld::ShortBits(pn.tag)},float(api->get_f(c,1))};
        QueueEventTo(e,pn.owner); ++ped_hits_sent;   // the owner's person: the owner's game applies it
      }
    api->set_f(c,1,0.0);
    return;
  }
  if(victim_slot>=0 && connected.load()) {
    // Host: one of its people (a mission enemy, a cop...) hit a client's
    // stand-in. That client's game applies it to the real player (with its
    // copy of that person as the attacker, or none).
    // 2.1: from any person here, not only the shared ones on foot: the police
    // response's units (82479AB0(4, ...), never on the ambient list) and
    // traffic crews hurt the stand-in to no effect. From people it doesn't
    // share only their own hits: not a car hitting the stand-in (82451C98:
    // the client's copy of the car hits there), nor explosions or fire (each
    // game plays those on its own player, R 3.0).
    // (3.0: by whichever game owns that person: here only this game's own, a copy's hit is its owner's to send)
    if(OwnsWorld() && attacker && attacker!=api->read_u32(0x8309ABEC) && Readable(attacker,4252) && api->read_u32(attacker+72)==1 &&
       AvatarSlotOf(attacker)<0 && !CarHitsPerson(api->get_lr(c)) && !OurCharacter(api->read_u32(attacker+68)) &&
       (WorldSends(api->read_u32(attacker+68),false) || (!explosion_depth && !fire_update_depth)) &&
       !((explosion_depth || fire_update_depth) && WorldMemberWithActions(victim_slot))) {   // (2.2 Package C: a member plays the host's people's explosions, projectiles and fire on its own player, R 3.0)
      const PersonNet pn=NetOfPerson(api->read_u32(attacker+68));   // (3.0: the attacker by its NetId; the hit goes even when no one else knows it: kNoPersonTag, no attacker there)
      Event e{kEventPlayerHitByPed,{pn.handle,uint32_t(api->get_r(c,5)),uint32_t(api->get_r(c,6)),uint32_t(api->get_r(c,7)),
                                    uint32_t(api->get_r(c,8)),uint32_t(api->get_r(c,9)),uint32_t(api->get_r(c,10)),
                                    uint32_t(api->read_u8(sp+87))|uint32_t(api->read_u8(sp+95))<<8|coopworld::ShortBits(pn.tag)},float(api->get_f(c,1))};
      QueueEventTo(e,uint8_t(victim_slot)); ++hits_from_people;
      api->set_f(c,1,0.0);
      return;
    }
    if(forward_damage && attacker==api->read_u32(0x8309ABEC) && !explosion_depth && !fire_update_depth) {   // (their game plays explosions and fire on its own player)
      Event e{kEventDamage,{uint32_t(api->get_r(c,5)),uint32_t(api->get_r(c,6)),uint32_t(api->get_r(c,7)),
                            uint32_t(api->get_r(c,8)),uint32_t(api->get_r(c,9)),uint32_t(api->get_r(c,10)),
                            api->read_u8(sp+87),api->read_u8(sp+95)},float(api->get_f(c,1))};
      QueueEventTo(e,uint8_t(victim_slot)); ++hits_sent;
    }
    api->set_f(c,1,0.0); // the stand-in never takes damage itself
    return;
  }
  original_damage(c,b);
}

