// 82444270(human, ...): starts a climb or vault when a ledge is in front.
// The other player's character here never starts one itself: it was pushed
// into walls by its move orders and began its own climb 0.3 s before theirs
// arrived, then climbed again (two climbs fighting). Their climb is replayed.
WmlGuestFunction original_climb_start=nullptr;
unsigned own_climbs_blocked=0;
// 3.0 (vault_climb_research.md 3.2): our player's climb goes to the other
// games as kEventClimb (where it started, the climb point and frame, who
// started it), as the game's own multiplayer does (823AFA88: the receiver
// finds the ledge again on its own copy and starts the climb there).
// mod.ini climb_sync = 0 (review_memfair L14): none of it - no kEventClimb
// sent or replayed, and the owner's climb states play on the character as
// before 3.0 (no fallback, no jump end on 6/E or 0/0, Drive's >2 m/s release
// as before).
bool climb_sync=true;
unsigned climbs_sent=0;
uint64_t climb_send_log_until=0;   // (the states and actions our player sends during its climb are logged: the sender's side of a climb)
inline uint32_t PackDir(const float* f);
inline void UnpackDir(uint32_t p,float* f);
void ClimbSendLog(const char* what,uint32_t a,uint32_t b) {
  static unsigned logged=0;
  if(MonoMs()>=climb_send_log_until || logged>=150) return;
  ++logged;
  char line[100]; std::snprintf(line,sizeof(line),"Climb: our player sends %s %X/%X",what,a,b); ProbeLog(line);
}
void ClimbStartHook(WmlContext* c,uint8_t* b) {
  const uint32_t h=uint32_t(api->get_r(c,3));
  if(connected.load() && !replicated_depth && AvatarSlotOf(h)>=0) {
    ++own_climbs_blocked; api->set_r(c,3,0); return;
  }
  const uint32_t r4=uint32_t(api->get_r(c,4)), r5=uint32_t(api->get_r(c,5));
  if(!climb_sync || !h || h!=api->read_u32(0x8309ABEC) || !connected.load() || replicated_depth || !Readable(h,600) || !Readable(r4,12) || !Readable(r5,36)) { original_climb_start(c,b); return; }
  float pos[3], pt[3], fwd[3];
  for(int i=0;i<3;++i) { pos[i]=api->read_f32(h+20+i*4); pt[i]=api->read_f32(r4+i*4); fwd[i]=api->read_f32(r5+24+i*4); }
  coopworld::ClimbInfo ci;
  ci.flag=uint8_t(api->get_r(c,6)); ci.state=uint8_t(api->read_u32(h+516)); ci.sub=uint8_t(api->read_u32(h+520));
  ci.caller=coopworld::ClimbCallerOf(uint32_t(api->get_lr(c)));
  const float yaw=std::atan2(api->read_f32(h+56),api->read_f32(h+64));
  const uint64_t log_was=climb_send_log_until;
  climb_send_log_until=MonoMs()+2500;   // (its own 5/x state goes out from inside the call)
  original_climb_start(c,b);
  if(uint32_t(api->get_r(c,3))!=1) { climb_send_log_until=log_was; return; }
  ci.new_sub=uint8_t(api->read_u32(h+520));
  Event e{kEventClimb,{},std::isfinite(yaw) ? yaw : 0.0f};
  std::memcpy(&e.a[0],pos,12); std::memcpy(&e.a[3],pt,12);
  e.a[6]=PackDir(fwd); e.a[7]=coopworld::PackClimbInfo(ci);
  QueueEvent(e); ++climbs_sent;
  static unsigned logged=0;
  if(logged++<40) {
    const float dx=pt[0]-pos[0], dy=pt[1]-pos[1], dz=pt[2]-pos[2];
    char line[200]; std::snprintf(line,sizeof(line),"Climb sent: from %s state %u/%X -> 5/%u, point %.1f %.1f %.1f, flag %u, ledge at %.2f m",
                                  coopworld::ClimbCallerName(ci.caller),ci.state,ci.sub,ci.new_sub,pt[0],pt[1],pt[2],ci.flag,std::sqrt(dx*dx+dy*dy+dz*dz));
    ProbeLog(line);
  }
}
