std::atomic<uint32_t> world_link_backlog[kSlots]{}, world_link_dropped[kSlots]{};   // network thread: the session's LinkStats per slot
std::atomic<uint32_t> world_eos_backlog{0};       // network thread: Epic's outgoing queue (all peers)
std::atomic<uint32_t> world_in_bytes{0}, world_admits_bad{0}, world_out_full{0};   // member: the bytes of the owner's world messages
// (3.0 phase 2c, shared) The viewer's backpressure: the bytes of each owner's
// world messages received here (network thread), and the bytes this game
// queued for each viewer (game thread). WWA1 carries the first; the owner
// halves a viewer's budget when over a quarter of the second never arrived.
// (review_phase2c M7) Both are running totals (u32, wrap-safe): a lost WWA1
// (it is unreliable) then costs nothing. The owner keeps its own total per
// viewer over the last 4 s (sampled each tick) and compares a report's window
// with its own as it was a round trip (and 150 ms) earlier; a window over a
// quarter short twice in a row is behind.
std::atomic<uint32_t> world_in_from[kSlots]{};
std::array<uint32_t,kSlots> world_out_to{};
std::array<std::deque<std::pair<uint64_t,uint32_t>>,kSlots> world_out_hist;   // owner, game thread: (time, world_out_to) each tick
struct ViewerReport { bool have=false, behind=false; uint32_t sent=0, received=0; };
std::array<ViewerReport,kSlots> world_viewer_rep;   // owner, game thread: each viewer's last WWA1 window
std::atomic<uint32_t> world_viewer_reset{0};        // network -> game thread: slots that are a new player (or left): their report and history start over (review_phase4 L8)
std::atomic<uint32_t> relay_rtt{0};   // network thread: a client's round trip to the session host (ms; the relay)
bool WorldRelayHold(uint64_t now);    // (3.0 phase 4, with WorldOwnersOut)
std::atomic<bool> world_relinked{false};   // network -> game thread (3.0 phase 4): a game linked again after a host migration
struct WorldBudgetCounts { unsigned busy_ticks=0, member_ticks=0, relayed_ticks=0, viewer_capped=0, viewer_behind=0; uint64_t sent_report=0, received_report=0; } world_budget_n;   // owner, 10 s

void WorldQueue(uint8_t type,uint8_t target,bool reliable,const void* data,size_t n) {
  std::lock_guard lock(world_mutex);
  if(world_out.size()>=4096) { ++world_out_full; return; }   // (the network thread fell behind)
  const uint8_t* p=static_cast<const uint8_t*>(data);
  world_out.push_back({type,target,reliable,std::vector<uint8_t>(p,p+n)});
  if(target<kSlots && (type==kMsgWorld || type==kMsgWorldCreate || type==kMsgWorldRemove || type==kMsgWorldDigest)) world_out_to[target]+=uint32_t(n);
}
